# EMF Report Deployer
# Double-click or right-click -> Run with PowerShell
# This script writes the report, verifies it, and pushes to GitHub.

Set-ExecutionPolicy -ExecutionPolicy Bypass -Scope Process -Force

$WorkDir = "C:\Users\Mike\uap_sniffer\uap_sniffer"
Set-Location $WorkDir

Write-Host ""
Write-Host "=== EMF Report Deployer ===" -ForegroundColor Cyan
Write-Host ""

# Ask for token
Write-Host "Paste your GitHub token (repo scope) and press Enter." -ForegroundColor Yellow
Write-Host "Get one at: https://github.com/settings/tokens" -ForegroundColor DarkGray
Write-Host ""
$Token = Read-Host "Token"
if (-not $Token) { Write-Host "No token entered. Exiting." -ForegroundColor Red; Read-Host; exit 1 }

# Write report via Python
Write-Host ""
Write-Host "Writing report files..." -ForegroundColor Cyan

$PyScript = @"
import base64, os, sys
encoded = ""
html = base64.b64decode(encoded).decode('utf-8')
os.makedirs('docs', exist_ok=True)
with open('docs\\index.html', 'w', encoding='utf-8') as f:
    f.write(html)
with open('phoenix_report.html', 'w', encoding='utf-8') as f:
    f.write(html)
with open('docs\\index.html', 'r', encoding='utf-8') as f:
    c = f.read()
checks = [
    ('Finding 01 present',    'Finding 01' in c),
    ('No stat-value class',   'stat-value' not in c),
    ('No land_grad',          'land_grad' not in c),
    ('GA tag present',        'G-M4LHPBSG83' in c),
    ('Map image before chart', c.index('phoenix_lights_map') < c.index('wavefront_plot')),
    ('AccessDenied present',  'AccessDenied' in c),
    ('IBM Plex present',      'IBM Plex' in c),
]
fail = False
for name, ok in checks:
    print(f"  {'OK' if ok else 'FAIL'}: {name}")
    if not ok: fail = True
sys.exit(1 if fail else 0)
"@

$PyScript | python
if ($LASTEXITCODE -ne 0) {
    Write-Host ""
    Write-Host "Content verification failed. Not pushing." -ForegroundColor Red
    Read-Host "Press Enter to exit"
    exit 1
}

Write-Host ""
Write-Host "All checks passed." -ForegroundColor Green

# Set remote with token
git remote set-url origin "https://$Token@github.com/Beastros/emf-anomaly-research.git"

# Stage, commit, push
Add-Content "docs\index.html" " "
git add docs\index.html phoenix_report.html
git commit -m "Clean data first report"

Write-Host ""
Write-Host "Pushing..." -ForegroundColor Cyan
git push origin main

if ($LASTEXITCODE -eq 0) {
    Write-Host ""
    Write-Host "Pushed successfully." -ForegroundColor Green
    Write-Host "Live in 1-3 minutes: https://beastros.github.io/emf-anomaly-research/" -ForegroundColor Cyan
} else {
    Write-Host ""
    Write-Host "Push failed. Check output above." -ForegroundColor Red
}

# Remove token from remote URL
git remote set-url origin "https://github.com/Beastros/emf-anomaly-research.git"

Write-Host ""
Read-Host "Press Enter to close"
